<?php
require_once 'config.php';require_role('admin');$pageTitle='Organization workspace';$uid=current_user()['id'];$s=$pdo->prepare('SELECT COUNT(*) FROM jobs WHERE posted_by=?');$s->execute([$uid]);$totalJobs=(int)$s->fetchColumn();$s=$pdo->prepare('SELECT COUNT(*) FROM applications a JOIN jobs j ON a.job_id=j.id WHERE j.posted_by=?');$s->execute([$uid]);$totalApps=(int)$s->fetchColumn();$s=$pdo->prepare("SELECT COUNT(*) FROM applications a JOIN jobs j ON a.job_id=j.id WHERE j.posted_by=? AND a.status='Submitted'");$s->execute([$uid]);$newApps=(int)$s->fetchColumn();$s=$pdo->prepare('SELECT j.*, (SELECT COUNT(*) FROM applications a WHERE a.job_id=j.id) AS application_count FROM jobs j WHERE j.posted_by=? ORDER BY j.created_at DESC');$s->execute([$uid]);$jobs=$s->fetchAll();$s=$pdo->prepare('SELECT a.id AS application_id,a.status,a.applied_at,a.resume,a.cover_note,u.name AS applicant_name,u.email,j.title,j.company_name FROM applications a JOIN users u ON u.id=a.user_id JOIN jobs j ON j.id=a.job_id WHERE j.posted_by=? ORDER BY a.applied_at DESC LIMIT 50');$s->execute([$uid]);$apps=$s->fetchAll();require 'includes/header.php'; ?>
<section class="dashboard-hero"><div><div class="eyebrow"><span class="eyebrow-dot"></span> ORGANIZATION WORKSPACE</div><h1>Build your <span class="text-accent">next team.</span></h1><p>Welcome back, <?= e(current_user()['name']) ?>. Here's what's happening with your opportunities.</p></div><a class="button button-primary" href="create_job.php">＋ Post an opportunity</a></section><section class="section dashboard-section"><div class="stats-grid"><article class="stat-card"><span class="stat-label">Opportunities posted</span><strong><?= $totalJobs ?></strong><span class="stat-foot"><span class="stat-dot dot-blue"></span> Total listings</span><span class="stat-symbol">▤</span></article><article class="stat-card"><span class="stat-label">Applications received</span><strong><?= $totalApps ?></strong><span class="stat-foot"><span class="stat-dot dot-green"></span> Across your roles</span><span class="stat-symbol">↗</span></article><article class="stat-card"><span class="stat-label">Need your attention</span><strong><?= $newApps ?></strong><span class="stat-foot"><span class="stat-dot dot-amber"></span> Awaiting review</span><span class="stat-symbol">◷</span></article></div><div class="listing-heading admin-list-heading"><div><h2>Your opportunities</h2><p>Manage live listings and see how candidates are responding.</p></div></div><?php if($jobs): ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Opportunity</th><th>Category</th><th>Applicants</th><th>Status</th><th>Manage</th></tr></thead><tbody><?php foreach($jobs as $j): ?><tr><td><strong><?= e($j['title']) ?></strong><small><?= e($j['location']) ?> · <?= date('M j, Y',strtotime($j['created_at'])) ?></small></td><td><?= e($j['category']) ?></td><td><span class="count-pill"><?= (int)$j['application_count'] ?></span></td><td><span class="status-pill status-<?= e($j['status']) ?>"><i></i><?= e(ucfirst($j['status'])) ?></span></td><td><a class="table-link" href="job.php?id=<?= (int)$j['id'] ?>">Preview ↗</a></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state"><div class="empty-icon">＋</div><h3>Your first opportunity starts here</h3><p>Create a listing and help someone take their next step.</p><a class="button button-primary" href="create_job.php">Post an opportunity ↗</a></div><?php endif; ?></section>
<section class="section review-section"><div class="listing-heading"><div><h2>Recent applications <span class="count-pill"><?= count($apps) ?></span></h2><p>Review applicants and update their application status.</p></div></div><?php if($apps): ?><div class="review-list"><?php foreach($apps as $app): ?><article class="review-card"><div class="avatar avatar-large"><?= e(initials($app['applicant_name'])) ?></div><div class="review-main"><h3><?= e($app['applicant_name']) ?></h3><p><?= e($app['email']) ?></p><span class="review-role">Applied for <strong><?= e($app['title']) ?></strong> · <?= date('M j, Y',strtotime($app['applied_at'])) ?></span><?php if($app['cover_note']): ?><details class="cover-note"><summary>Read applicant note</summary><p><?= nl2br(e($app['cover_note'])) ?></p></details><?php endif; ?></div><div class="review-actions"><a class="text-link" href="download_resume.php?id=<?= (int)$app['application_id'] ?>">Resume ↓</a><form method="post" action="update_status.php" class="status-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="application_id" value="<?= (int)$app['application_id'] ?>"><select name="status" aria-label="Update application status for <?= e($app['applicant_name']) ?>"><option <?= $app['status']==='Submitted'?'selected':'' ?>>Submitted</option><option <?= $app['status']==='Under Review'?'selected':'' ?>>Under Review</option><option <?= $app['status']==='Shortlisted'?'selected':'' ?>>Shortlisted</option><option <?= $app['status']==='Rejected'?'selected':'' ?>>Rejected</option><option <?= $app['status']==='Accepted'?'selected':'' ?>>Accepted</option></select><button class="button button-secondary button-small" type="submit">Update</button></form></div></article><?php endforeach; ?></div><?php else: ?><div class="empty-state compact-empty"><h3>No applications yet</h3><p>When students apply, their details will appear here.</p></div><?php endif; ?></section>
